import React, { useState, useEffect, useRef, useMemo } from 'react';
import {
  Sparkles,
  Play,
  Pause,
  RotateCcw,
  Feather,
  Sun,
  BookOpen,
  Code2,
  Copy,
  Check,
  Eye,
  Sliders,
  Maximize2,
  Minimize2,
} from 'lucide-react';

// 6-Color Palette from Bottom to Top (Down to Up)
const PALETTE = [
  { order: 0, hex: '#FFFDF7', name: 'Creamy White / Ivory', role: 'Unlimited Turning Pages & Stack' },
  { order: 1, hex: '#F9DAA4', name: 'Pale Peach / Wheat', role: 'Core Book Glow & Starlight' },
  { order: 2, hex: '#D1B27C', name: 'Warm Tan / Sand', role: 'Inner Halo & Page Highlights' },
  { order: 3, hex: '#B88556', name: 'Caramel / Toasted Almond', role: 'God-Rays & Illuminated Wood' },
  { order: 4, hex: '#B4682E', name: 'Copper / Amber Brown', role: 'Mid Aura & Quill Ink Shimmer' },
  { order: 5, hex: '#9E3E14', name: 'Burnt Orange / Terracotta', role: 'Deep Radial Glow & Wood Grain' },
  { order: 6, hex: '#6E3C1B', name: 'Dark Espresso / Chocolate', role: 'Outer Vignette & Table Planks' },
];

const REFERENCE_IMAGE = 'data:image/png;base64,';

/**
 * Reusable <MagicalShiningBook /> Component
 * Drop this directly into any parent React container (fills 100% width/height of its parent or uses custom height).
 */
export function MagicalShiningBook({
  isPlaying = true,
  flipSpeed = 1,
  glowIntensity = 1,
  starDensity = 1,
  enableSigning = true,
  direction = 'rtl', // 'rtl' (right-to-left) or 'ltr'
  manualFlipTrigger = 0,
  className = '',
}) {
  const canvasRef = useRef(null);
  const animationRef = useRef(null);
  const timeRef = useRef(0);
  const [signedPagesCount, setSignedPagesCount] = useState(128);

  // Precompute static rays for volumetric shine behind the book
  const lightRays = useMemo(() => {
    const rays = [];
    const count = 24;
    for (let i = 0; i < count; i++) {
      const angle = -82 + (i / (count - 1)) * 164;
      const width = 2.5 + ((i * 7) % 5) * 1.4;
      const length = 68 + ((i * 13) % 32);
      const opacity = 0.14 + ((i * 5) % 6) * 0.04;
      const speed = 0.7 + ((i * 3) % 5) * 0.35;
      const phase = (i * 1.3) % (Math.PI * 2);
      rays.push({ id: i, angle, width, length, opacity, speed, phase });
    }
    return rays;
  }, []);

  // Static fanned book pages on Left and Right stacks (Creamy White tones)
  const leftFanPages = useMemo(() => {
    return Array.from({ length: 11 }, (_, i) => ({
      id: i,
      angle: 3 + i * 1.8,
      curve: 10 + i * 1.6,
      shade: i % 2 === 0 ? '#FFFFFF' : '#FFF8E7',
    }));
  }, []);

  const rightFanPages = useMemo(() => {
    return Array.from({ length: 14 }, (_, i) => ({
      id: i,
      angle: -(2.5 + i * 2.2),
      curve: 12 + i * 2,
      shade: i % 2 === 0 ? '#FFFFFF' : '#FFF9EB',
    }));
  }, []);

  // Increment counter when manual flip triggers
  useEffect(() => {
    if (manualFlipTrigger > 0) {
      setSignedPagesCount((prev) => prev + 1);
    }
  }, [manualFlipTrigger]);

  // High-DPI Canvas for Swirling Star Plume, 8-Point Starbursts, and Dynamic Turning Pages
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');

    let width = (canvas.width = canvas.parentElement.clientWidth || 800);
    let height = (canvas.height = canvas.parentElement.clientHeight || 540);

    const handleResize = () => {
      if (!canvas.parentElement) return;
      width = canvas.width = canvas.parentElement.clientWidth;
      height = canvas.height = canvas.parentElement.clientHeight;
    };
    window.addEventListener('resize', handleResize);

    // Create Swirling Plume Particles (S-curve rising from spine like reference image)
    const maxPlumeStars = Math.floor(175 * starDensity);
    const plumeStars = Array.from({ length: maxPlumeStars }, (_, i) => ({
      progress: Math.random(), // 0 = book spine, 1 = top of screen
      spread: (Math.random() - 0.5) * 2,
      size: 1.2 + Math.random() * 3.8,
      speed: (0.0018 + Math.random() * 0.0028) * (0.7 + flipSpeed * 0.3),
      twinkleSpeed: 2 + Math.random() * 5,
      twinklePhase: Math.random() * Math.PI * 2,
      isStarburst: i % 5 === 0,
      color: i % 3 === 0 ? '#FFFFFF' : i % 3 === 1 ? '#F9DAA4' : '#D1B27C',
    }));

    // Create Scattered Ambient Starbursts in the Light Rays (left & right wings)
    const ambientStars = Array.from({ length: Math.floor(38 * starDensity) }, (_, i) => {
      const angle = (-0.92 + Math.random() * 1.84) * (Math.PI / 2);
      const dist = 0.22 + Math.random() * 0.58;
      return {
        angle,
        dist,
        size: 2.5 + Math.random() * 4.5,
        twinkleSpeed: 1.5 + Math.random() * 3.5,
        phase: Math.random() * Math.PI * 2,
        drift: (Math.random() - 0.5) * 0.0005,
      };
    });

    // Create Table Sparkle Reflections
    const tableSparkles = Array.from({ length: 24 }, () => ({
      xOffset: (Math.random() - 0.5) * 0.75,
      yOffset: 0.84 + Math.random() * 0.13,
      size: 1.2 + Math.random() * 2.4,
      phase: Math.random() * Math.PI * 2,
    }));

    // Helper to draw an 8-point glowing starburst exactly like the image
    const drawStarburst = (x, y, radius, alpha, tint = '#F9DAA4') => {
      if (alpha <= 0.02) return;
      ctx.save();
      ctx.translate(x, y);

      // Soft outer glow
      const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, radius * 3.2);
      grad.addColorStop(0, `rgba(255, 255, 255, ${Math.min(1, alpha)})`);
      grad.addColorStop(0.35, `rgba(249, 218, 164, ${alpha * 0.75})`);
      grad.addColorStop(0.7, `rgba(209, 178, 124, ${alpha * 0.28})`);
      grad.addColorStop(1, 'rgba(180, 104, 46, 0)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(0, 0, radius * 3.2, 0, Math.PI * 2);
      ctx.fill();

      // 4 Primary spikes + 4 Diagonal spikes
      ctx.strokeStyle = `rgba(255, 252, 242, ${Math.min(1, alpha * 0.95)})`;
      ctx.lineWidth = Math.max(0.8, radius * 0.32);
      ctx.beginPath();
      const spikeLen = radius * 2.8;
      ctx.moveTo(-spikeLen, 0);
      ctx.lineTo(spikeLen, 0);
      ctx.moveTo(0, -spikeLen);
      ctx.lineTo(0, spikeLen);
      ctx.stroke();

      ctx.strokeStyle = tint;
      ctx.globalAlpha = alpha * 0.7;
      ctx.lineWidth = Math.max(0.6, radius * 0.22);
      const diagLen = radius * 1.75;
      ctx.beginPath();
      ctx.moveTo(-diagLen, -diagLen);
      ctx.lineTo(diagLen, diagLen);
      ctx.moveTo(-diagLen, diagLen);
      ctx.lineTo(diagLen, -diagLen);
      ctx.stroke();

      ctx.restore();
    };

    // Helper to draw a creamy-white turning page opening unlimitedly from the right
    // Pages lift from the right stack and fan upward into the radiant light without transferring/slamming onto the left side
    const drawTurningPage = (
      spineX,
      spineY,
      pageWidth,
      pageHeight,
      progress, // 0 (peeling off right stack) -> 1 (fanned up in center-left light & dissolving)
      index
    ) => {
      // Smooth ease-out so pages peel gracefully from the right and slow down as they fan up into the light
      const eased = 1 - Math.pow(1 - progress, 1.65);

      // In 'rtl' (Unlimited Opening from Right), pages lift from right stack (0.055*PI) up to the high open fan (0.60*PI)
      // They NEVER transfer/drop onto the left stack; instead they open infinitely upward from the right!
      const startAngle = direction === 'rtl' ? 0.055 : 0.945;
      const endAngle = direction === 'rtl' ? 0.60 : 0.40;
      const theta = (startAngle + (endAngle - startAngle) * eased) * Math.PI;

      // Smooth fade-in as page separates from right stack, and smooth fade-out into the glowing starlight at peak fan
      const fadeIn = Math.min(1, progress / 0.14);
      const fadeOut = progress > 0.74 ? Math.max(0, (1 - progress) / 0.26) : 1;
      const pageAlpha = fadeIn * fadeOut;
      if (pageAlpha <= 0.01) return;

      // Tip of the page
      const cosT = Math.cos(theta);
      const sinT = Math.sin(theta);

      // Graceful upward paper curl as it opens from the right
      const curl = Math.sin(progress * Math.PI) * 28;
      const tipX = spineX + cosT * pageWidth;
      const tipY = spineY - sinT * (pageWidth * 0.82) - Math.sin(progress * Math.PI) * 22;

      // Control points for realistic S-bend paper arch
      const cp1X = spineX + cosT * (pageWidth * 0.46) + sinT * curl * 0.35;
      const cp1Y = spineY - sinT * (pageWidth * 0.42) - Math.abs(cosT) * 22;

      // Top edge of page in perspective (receding toward horizon)
      const depthX = (tipX - spineX) * 0.84;
      const depthLift = pageHeight * (0.52 + Math.sin(progress * Math.PI) * 0.22);
      const topSpineX = spineX;
      const topSpineY = spineY - pageHeight * 0.38;
      const topTipX = spineX + depthX;
      const topTipY = tipY - depthLift;
      const topCpX = spineX + (cp1X - spineX) * 0.88;
      const topCpY = cp1Y - depthLift * 0.94;

      ctx.save();
      ctx.globalAlpha = pageAlpha;

      // Luminous White-Creamy Page Surface Gradient
      const shineFactor = Math.sin(progress * Math.PI);
      const pageGrad = ctx.createLinearGradient(spineX, spineY, tipX, topTipY);
      pageGrad.addColorStop(0, '#F5E6C8');     // Warm cream at deep spine crease
      pageGrad.addColorStop(0.22, '#FFFDF9');  // Bright creamy white
      pageGrad.addColorStop(0.58, '#FFFFFF');  // Pure radiant white-cream highlight
      pageGrad.addColorStop(0.88, '#FFF9EE');  // Soft ivory cream
      pageGrad.addColorStop(1, '#FAF0DC');     // Creamy edge

      // Creamy white-gold aura around each opening page
      ctx.shadowColor = `rgba(255, 252, 240, ${(0.45 + shineFactor * 0.5) * glowIntensity})`;
      ctx.shadowBlur = 22 + shineFactor * 26;

      ctx.beginPath();
      ctx.moveTo(spineX, spineY);
      ctx.quadraticCurveTo(cp1X, cp1Y, tipX, tipY);
      ctx.lineTo(topTipX, topTipY);
      ctx.quadraticCurveTo(topCpX, topCpY, topSpineX, topSpineY);
      ctx.closePath();

      ctx.fillStyle = pageGrad;
      ctx.fill();

      // Crisp pure white-cream illuminated edge along the turning page
      ctx.lineWidth = 1.6 + shineFactor * 1.2;
      ctx.strokeStyle = `rgba(255, 255, 255, ${0.85 + shineFactor * 0.15})`;
      ctx.stroke();

      // Magical Golden Inscription & Signature ("signing") across the turning page
      if (enableSigning) {
        const writeProgress = Math.min(1, Math.max(0, (progress - 0.08) * 1.55));
        if (writeProgress > 0.05) {
          ctx.save();
          ctx.strokeStyle = `rgba(180, 104, 46, ${0.42 + shineFactor * 0.4})`;
          ctx.shadowColor = '#F9DAA4';
          ctx.shadowBlur = 8;
          ctx.lineWidth = 1.25;

          // Draw 3 shimmering calligraphy lines + signature flourish on the page surface
          for (let lineIdx = 0; lineIdx < 4; lineIdx++) {
            const vRatio = 0.25 + lineIdx * 0.18;
            const lineLen = lineIdx === 3 ? writeProgress * 0.55 : Math.min(1, writeProgress * 1.15);
            ctx.beginPath();
            const steps = 14;
            for (let s = 0; s <= steps; s++) {
              const u = (s / steps) * lineLen * 0.78 + 0.1;
              // Interpolate between bottom curve and top curve
              const bx = (1 - u) * (1 - u) * spineX + 2 * (1 - u) * u * cp1X + u * u * tipX;
              const by = (1 - u) * (1 - u) * spineY + 2 * (1 - u) * u * cp1Y + u * u * tipY;
              const tx =
                (1 - u) * (1 - u) * topSpineX + 2 * (1 - u) * u * topCpX + u * u * topTipX;
              const ty =
                (1 - u) * (1 - u) * topSpineY + 2 * (1 - u) * u * topCpY + u * u * topTipY;

              const wave =
                lineIdx === 3
                  ? Math.sin(s * 1.9 + index) * 3.8 // Signature flourish loop
                  : Math.sin(s * 2.4 + lineIdx) * 1.4;
              const px = bx + (tx - bx) * vRatio;
              const py = by + (ty - by) * vRatio + wave;

              if (s === 0) ctx.moveTo(px, py);
              else ctx.lineTo(px, py);
            }
            ctx.stroke();
          }

          // Glowing quill tip spark at the end of the signature while writing
          if (writeProgress < 0.96) {
            const uTip = writeProgress * 0.55 * 0.78 + 0.1;
            const bx =
              (1 - uTip) * (1 - uTip) * spineX + 2 * (1 - uTip) * uTip * cp1X + uTip * uTip * tipX;
            const by =
              (1 - uTip) * (1 - uTip) * spineY + 2 * (1 - uTip) * uTip * cp1Y + uTip * uTip * tipY;
            const tx =
              (1 - uTip) * (1 - uTip) * topSpineX +
              2 * (1 - uTip) * uTip * topCpX +
              uTip * uTip * topTipX;
            const ty =
              (1 - uTip) * (1 - uTip) * topSpineY +
              2 * (1 - uTip) * uTip * topCpY +
              uTip * uTip * topTipY;
            const sparkX = bx + (tx - bx) * 0.79;
            const sparkY = by + (ty - by) * 0.79;
            drawStarburst(sparkX, sparkY, 3.2, 0.92, '#FFFDF5');
          }
          ctx.restore();
        }
      }

      ctx.restore();
    };

    let lastTime = performance.now();

    const render = (now) => {
      const dt = Math.min(0.05, (now - lastTime) / 1000);
      lastTime = now;

      if (isPlaying) {
        timeRef.current += dt * flipSpeed;
      }
      const t = timeRef.current;

      ctx.clearRect(0, 0, width, height);

      const spineX = width * 0.5;
      const spineY = height * 0.815;
      const bookRadius = Math.min(width * 0.3, 215);

      // 1. Central Intense Golden Burst behind the Book Spine
      const coreGlowRadius = Math.max(width, height) * 0.58;
      const burstGrad = ctx.createRadialGradient(
        spineX,
        spineY - 42,
        8,
        spineX,
        spineY - 50,
        coreGlowRadius
      );
      const gMult = Math.min(1.35, Math.max(0.3, glowIntensity));
      burstGrad.addColorStop(0, `rgba(255, 253, 245, ${0.96 * gMult})`);
      burstGrad.addColorStop(0.14, `rgba(249, 218, 164, ${0.86 * gMult})`); // #F9DAA4
      burstGrad.addColorStop(0.3, `rgba(209, 178, 124, ${0.58 * gMult})`); // #D1B27C
      burstGrad.addColorStop(0.48, `rgba(184, 133, 86, ${0.38 * gMult})`); // #B88556
      burstGrad.addColorStop(0.66, `rgba(180, 104, 46, ${0.22 * gMult})`); // #B4682E
      burstGrad.addColorStop(0.84, `rgba(158, 62, 20, ${0.11 * gMult})`); // #9E3E14
      burstGrad.addColorStop(1, 'rgba(110, 60, 27, 0)'); // #6E3C1B

      ctx.fillStyle = burstGrad;
      ctx.fillRect(0, 0, width, height * 0.84);

      // 2. Ambient Wing Starbursts along the Volumetric Rays
      ambientStars.forEach((star) => {
        if (isPlaying) {
          star.angle += star.drift * flipSpeed;
        }
        const r = Math.min(width, height) * star.dist * 0.95;
        const sx = spineX + Math.sin(star.angle) * r * 1.25;
        const sy = spineY - 30 - Math.cos(star.angle) * r * 0.88;
        const pulse = 0.45 + 0.55 * Math.sin(t * star.twinkleSpeed + star.phase);
        drawStarburst(sx, sy, star.size * (0.75 + pulse * 0.35), pulse * 0.85 * gMult, '#F9DAA4');
      });

      // 3. Swirling S-Curve Starlight Plume Rising from the Turning Pages (Signature Visual from Image)
      plumeStars.forEach((p) => {
        if (isPlaying) {
          p.progress += p.speed;
          if (p.progress >= 1) {
            p.progress = 0;
            p.spread = (Math.random() - 0.5) * 2;
          }
        }

        const pr = p.progress;
        // S-curve centerline matching the uploaded reference photo
        const sCurveOffset =
          Math.sin(pr * Math.PI * 2.15 - 0.4) * (width * 0.075 * pr) -
          Math.cos(pr * Math.PI * 1.1) * (width * 0.025);
        const plumeWidth = 18 + pr * (width * 0.095) * (1 - pr * 0.35);

        const px = spineX + sCurveOffset + p.spread * plumeWidth;
        const py = spineY - 22 - pr * (spineY - 12);

        const fadeEdge = pr < 0.12 ? pr / 0.12 : pr > 0.88 ? (1 - pr) / 0.12 : 1;
        const twinkle = 0.5 + 0.5 * Math.sin(t * p.twinkleSpeed + p.twinklePhase);
        const alpha = fadeEdge * (0.45 + twinkle * 0.55) * gMult;

        if (p.isStarburst) {
          drawStarburst(px, py, p.size * 0.9, alpha, p.color);
        } else {
          ctx.save();
          const dotGrad = ctx.createRadialGradient(px, py, 0, px, py, p.size * 2.2);
          dotGrad.addColorStop(0, `rgba(255, 255, 255, ${alpha})`);
          dotGrad.addColorStop(0.45, `rgba(249, 218, 164, ${alpha * 0.8})`);
          dotGrad.addColorStop(1, 'rgba(209, 178, 124, 0)');
          ctx.fillStyle = dotGrad;
          ctx.beginPath();
          ctx.arc(px, py, p.size * 2.2, 0, Math.PI * 2);
          ctx.fill();
          ctx.restore();
        }
      });

      // 4. Unlimited Creamy-White Pages Continuously Opening from the Right
      const activePageCount = 6;
      const pageHeight = Math.min(height * 0.25, 136);
      const pagesToRender = [];
      for (let i = 0; i < activePageCount; i++) {
        const rawPhase = (t * 0.34 + i / activePageCount) % 1;
        pagesToRender.push({ phase: rawPhase, index: i });
      }
      // Draw higher-lifted pages first and newly peeling right-side pages on top of the right stack in natural order
      pagesToRender.sort((a, b) => b.phase - a.phase);
      pagesToRender.forEach((item) => {
        drawTurningPage(spineX, spineY, bookRadius * 0.94, pageHeight, item.phase, item.index);
      });

      // 5. Intense Spine Seam Core Light (where pages meet)
      const seamGrad = ctx.createRadialGradient(spineX, spineY - 12, 2, spineX, spineY - 18, 68);
      seamGrad.addColorStop(0, `rgba(255, 255, 255, ${0.95 * gMult})`);
      seamGrad.addColorStop(0.4, `rgba(249, 218, 164, ${0.72 * gMult})`);
      seamGrad.addColorStop(1, 'rgba(249, 218, 164, 0)');
      ctx.fillStyle = seamGrad;
      ctx.beginPath();
      ctx.arc(spineX, spineY - 12, 68, 0, Math.PI * 2);
      ctx.fill();

      // 6. Table Surface Sparkles & Warm Reflection
      tableSparkles.forEach((sp) => {
        const tx = spineX + sp.xOffset * width;
        const ty = height * sp.yOffset;
        const pulse = 0.35 + 0.65 * Math.sin(t * 2.8 + sp.phase);
        drawStarburst(tx, ty, sp.size, pulse * 0.65 * gMult, '#F9DAA4');
      });

      animationRef.current = requestAnimationFrame(render);
    };

    animationRef.current = requestAnimationFrame(render);
    return () => {
      window.removeEventListener('resize', handleResize);
      if (animationRef.current) cancelAnimationFrame(animationRef.current);
    };
  }, [isPlaying, flipSpeed, glowIntensity, starDensity, enableSigning, direction]);

  return (
    <div
      className={`relative w-full h-full overflow-hidden select-none bg-[#070301] ${className}`}
      style={{ minHeight: '460px' }}
    >
      {/* Ambient Deep Background Gradient using #6E3C1B -> #9E3E14 -> #B4682E -> #F9DAA4 */}
      <div
        className="absolute inset-0 pointer-events-none"
        style={{
          background: `radial-gradient(ellipse 72% 62% at 50% 78%,
            rgba(249, 218, 164, ${0.65 * glowIntensity}) 0%,
            rgba(209, 178, 124, ${0.48 * glowIntensity}) 18%,
            rgba(184, 133, 86, ${0.36 * glowIntensity}) 34%,
            rgba(180, 104, 46, ${0.26 * glowIntensity}) 50%,
            rgba(158, 62, 20, ${0.16 * glowIntensity}) 66%,
            rgba(110, 60, 27, ${0.12 * glowIntensity}) 78%,
            #060301 96%)`,
        }}
      />

      {/* Volumetric Shining God-Rays Fanning Out from the Book */}
      <div
        className="absolute inset-0 pointer-events-none overflow-hidden"
        style={{ opacity: Math.min(1, glowIntensity * 0.95) }}
      >
        {lightRays.map((ray) => (
          <div
            key={ray.id}
            className="absolute origin-bottom pointer-events-none"
            style={{
              left: '50%',
              bottom: '18.5%',
              width: `${ray.width}%`,
              height: `${ray.length}%`,
              transform: `translateX(-50%) rotate(${ray.angle}deg)`,
              background:
                'linear-gradient(to top, rgba(249,218,164,0.52) 0%, rgba(209,178,124,0.24) 45%, rgba(184,133,86,0.06) 80%, transparent 100%)',
              filter: 'blur(6px)',
              opacity: ray.opacity,
              animation: isPlaying
                ? `rayPulse ${3.2 / ray.speed}s ease-in-out ${ray.phase}s infinite alternate`
                : 'none',
            }}
          />
        ))}
      </div>

      {/* Perspective Wooden Table Surface (Bottom 19% of Container) */}
      <div
        className="absolute bottom-0 left-0 right-0 h-[19.5%] pointer-events-none"
        style={{
          background:
            'linear-gradient(180deg, #4B2811 0%, #6E3C1B 18%, #8B4E24 48%, #6E3C1B 82%, #3D1F0D 100%)',
          boxShadow: 'inset 0 12px 28px rgba(0,0,0,0.75)',
        }}
      >
        {/* Warm Golden Table Reflection Directly Under the Open Book */}
        <div
          className="absolute inset-0"
          style={{
            background: `radial-gradient(ellipse 48% 70% at 50% 8%,
              rgba(249, 218, 164, ${0.55 * glowIntensity}) 0%,
              rgba(209, 178, 124, ${0.32 * glowIntensity}) 38%,
              rgba(180, 104, 46, 0.12) 68%,
              transparent 100%)`,
          }}
        />

        {/* SVG Wood Grain Texture & Perspective Plank Seams */}
        <svg
          viewBox="0 0 1000 160"
          preserveAspectRatio="none"
          className="w-full h-full opacity-85"
        >
          <defs>
            <linearGradient id="plankShadow" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor="#1A0B04" stopOpacity="0.85" />
              <stop offset="100%" stopColor="#090301" stopOpacity="0.95" />
            </linearGradient>
            <linearGradient id="woodSheen" x1="0" y1="0" x2="1" y2="0">
              <stop offset="0%" stopColor="#3B1E0D" stopOpacity="0.6" />
              <stop offset="22%" stopColor="#9E3E14" stopOpacity="0.25" />
              <stop offset="50%" stopColor="#F9DAA4" stopOpacity="0.22" />
              <stop offset="78%" stopColor="#9E3E14" stopOpacity="0.25" />
              <stop offset="100%" stopColor="#3B1E0D" stopOpacity="0.6" />
            </linearGradient>
          </defs>

          <rect x="0" y="0" width="1000" height="160" fill="url(#woodSheen)" />
          {/* Top horizon edge line */}
          <line x1="0" y1="1.5" x2="1000" y2="1.5" stroke="#261206" strokeWidth="3" />

          {/* Perspective plank grooves */}
          <path d="M 140 0 L -40 160" stroke="url(#plankShadow)" strokeWidth="4.5" />
          <path d="M 275 0 L 165 160" stroke="url(#plankShadow)" strokeWidth="4" />
          <path d="M 395 0 L 350 160" stroke="url(#plankShadow)" strokeWidth="3.5" />
          <path d="M 500 0 L 500 160" stroke="url(#plankShadow)" strokeWidth="3.5" />
          <path d="M 605 0 L 650 160" stroke="url(#plankShadow)" strokeWidth="3.5" />
          <path d="M 725 0 L 835 160" stroke="url(#plankShadow)" strokeWidth="4" />
          <path d="M 860 0 L 1040 160" stroke="url(#plankShadow)" strokeWidth="4.5" />

          {/* Subtle organic wood grain knots and fibers */}
          <path
            d="M 190 45 Q 240 52 270 46 M 360 95 Q 420 82 475 98 M 530 70 Q 590 62 630 74 M 700 110 Q 765 102 810 118"
            stroke="#2B1407"
            strokeWidth="1.4"
            fill="none"
            opacity="0.45"
          />
        </svg>
      </div>

      {/* Static Base of the Open Book (Hardcover + Left & Right Fanned Page Stacks) */}
      <div className="absolute inset-x-0 bottom-[13.5%] h-[32%] flex items-end justify-center pointer-events-none">
        <svg
          viewBox="0 0 800 240"
          className="w-[88%] max-w-[660px] h-auto overflow-visible drop-shadow-[0_14px_24px_rgba(0,0,0,0.88)]"
        >
          <defs>
            <linearGradient id="pageStackLeft" x1="0" y1="0" x2="1" y2="0">
              <stop offset="0%" stopColor="#E8D7B9" />
              <stop offset="30%" stopColor="#FAF0DC" />
              <stop offset="75%" stopColor="#FFFDF8" />
              <stop offset="100%" stopColor="#FFFFFF" />
            </linearGradient>
            <linearGradient id="pageStackRight" x1="1" y1="0" x2="0" y2="0">
              <stop offset="0%" stopColor="#E8D7B9" />
              <stop offset="30%" stopColor="#FAF0DC" />
              <stop offset="75%" stopColor="#FFFDF8" />
              <stop offset="100%" stopColor="#FFFFFF" />
            </linearGradient>
            <linearGradient id="bookCover" x1="0" y1="0" x2="1" y2="0">
              <stop offset="0%" stopColor="#1B1310" />
              <stop offset="46%" stopColor="#33221A" />
              <stop offset="50%" stopColor="#120B07" />
              <stop offset="54%" stopColor="#33221A" />
              <stop offset="100%" stopColor="#1B1310" />
            </linearGradient>
          </defs>

          {/* Soft Ground Contact Shadow on the Wood Table */}
          <ellipse cx="400" cy="216" rx="285" ry="14" fill="rgba(0,0,0,0.78)" />

          {/* Left Fanned Page Stack */}
          {leftFanPages.map((p) => {
            const yOffset = 198 - p.id * 4.4;
            const xOuter = 138 + p.id * 3.8;
            const yOuter = 192 - p.id * 7.8;
            const cpX = 275 + p.id * 1.5;
            const cpY = 175 - p.id * 7.2;
            return (
              <g key={`left-${p.id}`}>
                <path
                  d={`M 400 202 Q ${cpX} ${cpY} ${xOuter} ${yOuter} L ${xOuter + 14} ${
                    yOuter - 16
                  } Q ${cpX + 8} ${cpY - 14} 400 184 Z`}
                  fill="url(#pageStackLeft)"
                  stroke="#D8C39E"
                  strokeWidth="0.65"
                  opacity={0.78 + p.id * 0.02}
                />
                <path
                  d={`M 400 ${yOffset} Q ${cpX} ${cpY} ${xOuter} ${yOuter}`}
                  fill="none"
                  stroke={p.shade}
                  strokeWidth="1.35"
                />
              </g>
            );
          })}

          {/* Right Fanned Page Stack */}
          {rightFanPages.map((p) => {
            const yOffset = 198 - p.id * 4.4;
            const xOuter = 662 - p.id * 3.8;
            const yOuter = 192 - p.id * 7.8;
            const cpX = 525 - p.id * 1.5;
            const cpY = 175 - p.id * 7.2;
            return (
              <g key={`right-${p.id}`}>
                <path
                  d={`M 400 202 Q ${cpX} ${cpY} ${xOuter} ${yOuter} L ${xOuter - 14} ${
                    yOuter - 16
                  } Q ${cpX - 8} ${cpY - 14} 400 184 Z`}
                  fill="url(#pageStackRight)"
                  stroke="#D8C39E"
                  strokeWidth="0.65"
                  opacity={0.78 + p.id * 0.02}
                />
                <path
                  d={`M 400 ${yOffset} Q ${cpX} ${cpY} ${xOuter} ${yOuter}`}
                  fill="none"
                  stroke={p.shade}
                  strokeWidth="1.35"
                />
              </g>
            );
          })}

          {/* Hardcover Book Base & Spine Clasp */}
          <path
            d="M 118 208 L 382 206 C 390 215, 410 215, 418 206 L 682 208 L 694 214 L 422 214 C 412 222, 388 222, 378 214 L 106 214 Z"
            fill="url(#bookCover)"
            stroke="#D1B27C"
            strokeWidth="0.8"
          />
          {/* Spine Binding Hinge Detail */}
          <path
            d="M 384 206 Q 400 196 416 206 L 414 215 Q 400 220 386 215 Z"
            fill="#1D120C"
            stroke="#B88556"
            strokeWidth="1"
          />
          <circle cx="394" cy="211" r="1.4" fill="#F9DAA4" />
          <circle cx="400" cy="211" r="1.4" fill="#F9DAA4" />
          <circle cx="406" cy="211" r="1.4" fill="#F9DAA4" />
        </svg>
      </div>

      {/* Main High-DPI Interactive Canvas (Turning Pages + Swirling Stars + Glowing Quill Signing) */}
      <canvas ref={canvasRef} className="absolute inset-0 w-full h-full pointer-events-none" />

      {/* Subtle Floating Status Pill in Top-Left */}
      <div className="absolute top-3 left-3 flex items-center gap-2 px-3 py-1.5 rounded-full bg-black/55 backdrop-blur-md border border-[#D1B27C]/30 text-xs text-[#F9DAA4]">
        <span className="w-2 h-2 rounded-full bg-[#F9DAA4] animate-ping" />
        <span className="font-medium tracking-wide">
          {isPlaying ? 'Pages Turning & Shining' : 'Animation Paused'}
        </span>
        {enableSigning && (
          <span className="text-[#D1B27C] border-l border-[#D1B27C]/30 pl-2 flex items-center gap-1">
            <Feather className="w-3 h-3 text-[#F9DAA4]" />
            Signed #{signedPagesCount}
          </span>
        )}
      </div>

      <style>{`
        @keyframes rayPulse {
          0% { opacity: 0.12; transform: translateX(-50%) scaleY(0.94); }
          100% { opacity: 0.44; transform: translateX(-50%) scaleY(1.06); }
        }
      `}</style>
    </div>
  );
}
